def period(y):
    for a, b, p in [(0, 1496, '15th century'), (1497, 1559, '1497-1559'), (1560, 1589, '1560-1589'), (1590, 1598, '1589-1598'),
                    (1599, 1610, '1598-1610'), (1611, 1650, '1611-1650'), (1651, 1700, '1651-1700'), (1701, 1800, '1701-1800'),
                    (1801, 1900, '1801-1900'), (1901, 1950, '1901-1950')]:
        if a <= y <= b:
            return p
    return 'unknown'


def row(year, date, title, corr, place, lang, region, shelf, folio, cls, status, why, imp, sol, dif, verify, links, source,
        scan='yes', access='Reading-room item; no scan found online', prior=CHECKED):
    return dict(year=year, date=date, title=title, correspondents=corr, place=place, language=lang, region=region,
                period=period(year), shelfmark=shelf, folio_note=folio, cls=cls, status=status, why=why, importance=imp,
                solvability=sol, difficulty=dif,
                score_note=f'Scored from the archive description during the Nov 2026 US blocked-sources sweep '
                           f'(research/sweep_2026-11_us_blocked/); not viewed',
                verify=verify, links=links, seen='catalogue', source=source, prior_art=prior,
                needs_archive_scan=scan, access_note=access, decode_ids=[])


def ag(n, label='ArchiveGrid record'):
    return [{'label': label, 'href': AG + str(n)}]


